# Exact source lines behind every evidence-gallery chart point, keyed by S#.
# Request-scoped (one value per report task) and read by both audit-source
# builders so the same quoted lines verify the charts at report time and are
# carried in the public manifest for export-time chart audits.
_CHART_EVIDENCE_LINES: "_contextvars.ContextVar[dict]" = _contextvars.ContextVar("gg_chart_evidence_lines", default={})
_PUBLISHER_TABLE_CHART_EVIDENCE_IDS: "_contextvars.ContextVar[set]" = _contextvars.ContextVar("gg_publisher_table_chart_evidence_ids", default=set())
_PUBLISHER_GALLERY_CHART_EVIDENCE_IDS: "_contextvars.ContextVar[set]" = _contextvars.ContextVar("gg_publisher_gallery_chart_evidence_ids", default=set())
_SEARCH_GALLERY_CHART_EVIDENCE_IDS: "_contextvars.ContextVar[set]" = _contextvars.ContextVar("gg_search_gallery_chart_evidence_ids", default=set())
_PUBLISHER_GALLERY_CHART_EVIDENCE_LINES: "_contextvars.ContextVar[dict]" = _contextvars.ContextVar("gg_publisher_gallery_chart_evidence_lines", default={})
_SEARCH_GALLERY_CHART_EVIDENCE_LINES: "_contextvars.ContextVar[dict]" = _contextvars.ContextVar("gg_search_gallery_chart_evidence_lines", default={})


def _search_extract_evidence_allowed() -> bool:
    """Whether a search-index extract may verify a figure when the publisher page could not be fetched.

    Exa/Tavily extracts are the provider's own indexed copy of the cited page.
    Matching remains strict (same sentence/row, value, unit and subject terms);
    only the publisher-fetch prerequisite is relaxed. Set
    REPORT_ACCEPT_SEARCH_EXTRACT_EVIDENCE=0 to restore publisher-page-only checks.
    """
    return os.getenv("REPORT_ACCEPT_SEARCH_EXTRACT_EVIDENCE", "1").strip().casefold() not in {"0", "false", "no", "off"}


def _chart_evidence_lines_for_kind(source_id: object, kind: str) -> str:
    registry = _PUBLISHER_GALLERY_CHART_EVIDENCE_LINES if kind == "publisher" else _SEARCH_GALLERY_CHART_EVIDENCE_LINES
    lines = (registry.get() or {}).get(str(source_id or "").strip().upper()) or []
    if isinstance(lines, str):
        return lines[:16000]
    if isinstance(lines, (list, tuple, set)):
        return "\n".join(str(line) for line in lines if line)[:16000]
    return str(lines)[:16000]


def _normalize_chart_evidence_excerpt(value: object) -> str:
    """Normalize row formatting without relaxing numeric or cell-order matching.

    Structured publisher extraction often preserves a table row as plain text,
    while the search index wraps that same row in leading/trailing Markdown pipes.
    Trim only those outer pipes and normalize whitespace around internal pipes.
    Values, units, cell order, and punctuation remain part of the comparison.
    """
    normalized_lines: list[str] = []
    for raw_line in re.split(r"[\r\n]+", str(value or "")):
        line = re.sub(r"\s+", " ", raw_line).strip().casefold()
        line = re.sub(r"^\|+\s*", "", line)
        line = re.sub(r"\s*\|+$", "", line)
        line = re.sub(r"\s*\|\s*", "|", line)
        if line:
            normalized_lines.append(line)
    return "\n".join(normalized_lines)


def _chart_excerpt_matches_source_text(quote: object, source_text: object) -> bool:
    normalized_quote = _normalize_chart_evidence_excerpt(quote)
    normalized_source = _normalize_chart_evidence_excerpt(source_text)
    return bool(normalized_quote and normalized_quote in normalized_source)


def _chart_evidence_lines_for(source_id: object) -> str:
    lines = (_CHART_EVIDENCE_LINES.get() or {}).get(str(source_id or "").strip().upper()) or []
    # The evidence-gallery writer stores a list of excerpts, while the verified
    # table-to-chart builder stores an already-joined string. Treat both formats
    # explicitly: joining a string as an iterable inserts a newline between every
    # character and makes every subsequent source-quote audit fail.
    if isinstance(lines, str):
        return lines[:16000]
    if isinstance(lines, (list, tuple, set)):
        return "\n".join(str(line) for line in lines if line)[:16000]
    return str(lines)[:16000]
