    "below", "over", "under", "between", "against", "respectively", "implication", "source",
    "sources", "report", "data", "figure", "table", "chart", "trend", "trends", "value",
    "values", "metric", "metrics", "current", "previous", "latest", "approximately", "around",
    "nearly", "more", "less", "than", "into", "after", "before", "same", "were", "been", "have",
